package com.arman.bank.sso;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

class CodeIntentFixtureLaunchConfigurationTest {
    static Map<String,String> enabled(){var values=CodeIntentFixtureBootstrapTest.config();var s=CodeIntentFixtureBootstrapTest.settings();
        values.put("ARMONEY_CODE_INTENT_FIXTURE_ENABLED","true");values.put("CI","true");values.put("CODE_SESSION_ACCEPTANCE_ISOLATED","true");
        values.put("ARMONEY_CODE_INTENT_FIXTURE_CONTROL_KEY",s.controllerKey());values.put("ARMONEY_FIXTURE_PEER_KEY",s.peerKey());values.put("AUTH_CODE_INTENT_FIXTURE_PROVIDER_KEY",s.providerKey());
        values.put("ARMONEY_CODE_INTENT_FIXTURE_SUBJECT",s.subject());values.put("ARMONEY_CODE_INTENT_FIXTURE_LOCAL_MATERIAL","{\"current\":\""+Base64.getEncoder().encodeToString(CodeIntentFixtureBootstrapTest.materials().get("current"))+"\"}");return values;}
    @Test void offIsTerminalAndNeverAllocates(){var starts=new AtomicInteger();var launch=new CodeIntentFixtureLaunchConfiguration((c,m,s)->{starts.incrementAndGet();throw new AssertionError();});
        assertTrue(launch.configure(Map.of()).isEmpty());launch.startConfigured();assertTrue(launch.configure(Map.of()).isEmpty());assertThrows(IllegalStateException.class,()->launch.configure(enabled()));launch.close();assertThrows(IllegalStateException.class,launch::startConfigured);assertEquals(0,starts.get());}
    @Test void falseIsOffAndMalformedOrMissingGatesCannotAllocate(){for(String gate:CodeIntentFixtureLaunchConfiguration.GATES){var values=enabled();values.put(gate,"TRUE");var starts=new AtomicInteger();var launch=new CodeIntentFixtureLaunchConfiguration((c,m,s)->{starts.incrementAndGet();return ()->{};});assertThrows(IllegalStateException.class,()->launch.configure(values));assertThrows(IllegalStateException.class,launch::startConfigured);assertEquals(0,starts.get());launch.close();}
        var off=new CodeIntentFixtureLaunchConfiguration();assertTrue(off.configure(Map.of(CodeIntentFixtureLaunchConfiguration.ENABLED,"false")).isEmpty());off.close();}
    @Test void unknownAndInvalidIdentityFailBeforeStart(){for(String name:List.of("UNKNOWN_SECRET","ARMONEY_CODE_INTENT_FIXTURE_SUBJECT","ARMONEY_AUTH_BRIDGE_URL")){var values=enabled();values.put(name,"private-invalid");var launch=new CodeIntentFixtureLaunchConfiguration((c,m,s)->{throw new AssertionError("No allocation");});var error=assertThrows(IllegalStateException.class,()->launch.configure(values));assertNull(error.getCause());assertFalse(error.toString().contains("private-invalid"));launch.close();}}
    @Test void duplicateConfigureStartAndCloseAreAllocationIdempotent(){var starts=new AtomicInteger();var closes=new AtomicInteger();var launch=new CodeIntentFixtureLaunchConfiguration((c,m,s)->{starts.incrementAndGet();return closes::incrementAndGet;});var values=enabled();assertSame(launch,launch.configure(values).orElseThrow());assertSame(launch,launch.configure(new HashMap<>(values)).orElseThrow());launch.startConfigured();launch.startConfigured();assertSame(launch,launch.configure(values).orElseThrow());values.put("SSO_LOGIN_PROOF_WRITE_KEY","different");assertThrows(IllegalStateException.class,()->launch.configure(values));launch.close();launch.close();assertEquals(1,starts.get());assertEquals(1,closes.get());assertThrows(IllegalStateException.class,()->launch.configure(enabled()));}
    @Test void configuredValuesAndMaterialAreDefensivelyCopied(){var values=enabled();var launch=new CodeIntentFixtureLaunchConfiguration((c,m,s)->{assertEquals("w".repeat(40),c.get("SSO_LOGIN_PROOF_WRITE_KEY"));assertEquals(7,m.get("current")[0]);assertThrows(UnsupportedOperationException.class,()->c.clear());m.get("current")[0]=99;return ()->{};});launch.configure(values);values.clear();launch.startConfigured();launch.close();}
    @Test void failedStartIsTerminalAndRedacted(){var starts=new AtomicInteger();var launch=new CodeIntentFixtureLaunchConfiguration((c,m,s)->{starts.incrementAndGet();throw new IllegalStateException("private-start-value");});launch.configure(enabled());var error=assertThrows(IllegalStateException.class,launch::startConfigured);assertNull(error.getCause());assertFalse(error.toString().contains("private-start-value"));assertThrows(IllegalStateException.class,launch::startConfigured);assertThrows(IllegalStateException.class,()->launch.configure(enabled()));launch.close();assertEquals(1,starts.get());}
    @Test void strictMaterialRejectsDuplicateKindsBomSurrogatesAndNoncanonicalBase64(){for(String json:List.of("{}","[]","{\"a\":null}","{\"a\":1}","{\"a\":{}}","{\"a\":\"YQ==\",\"a\":\"Yg==\"}","{\"a\":\"YQ\"}","{\"a\":\"YQ==\\n\"}","\uFEFF{}","{\"a\":\"\uD800\"}","{\"bad key\":\"YQ==\"}","{\"a\":\"\"}")){
        var error=assertThrows(IllegalStateException.class,()->CodeIntentFixtureLaunchConfiguration.decode(json));assertNull(error.getCause());}
        assertEquals(1,CodeIntentFixtureLaunchConfiguration.decode("{\"a\":\"YQ==\"}").get("a").length);}
    @Test void materialBoundsAndCodeKeyLengthAreEnforced(){String big=Base64.getEncoder().encodeToString(new byte[4097]);assertThrows(IllegalStateException.class,()->CodeIntentFixtureLaunchConfiguration.decode("{\"a\":\""+big+"\"}"));
        var entries=new ArrayList<String>();for(int i=0;i<65;i++)entries.add("\"k"+i+"\":\"YQ==\"");assertThrows(IllegalStateException.class,()->CodeIntentFixtureLaunchConfiguration.decode("{"+String.join(",",entries)+"}"));
        assertThrows(IllegalStateException.class,()->CodeIntentFixtureLaunchConfiguration.decode(" ".repeat(16385)+"{}"));var values=enabled();values.put("ARMONEY_CODE_INTENT_FIXTURE_LOCAL_MATERIAL","{\"current\":\"YQ==\"}");assertThrows(IllegalStateException.class,()->new CodeIntentFixtureLaunchConfiguration().configure(values));}
    @Test void startAndCloseSerializeWithoutInstallationAfterCloseReturns()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var closeAttempt=new CountDownLatch(1);var closed=new AtomicInteger();
        var launch=new CodeIntentFixtureLaunchConfiguration((c,m,s)->{entered.countDown();try{assertTrue(release.await(2,TimeUnit.SECONDS));}catch(InterruptedException e){throw new AssertionError(e);}return closed::incrementAndGet;});launch.configure(enabled());
        var start=new FutureTask<Void>(()->{launch.startConfigured();return null;});var close=new FutureTask<Void>(()->{closeAttempt.countDown();launch.close();return null;});var a=new Thread(start);var b=new Thread(close);a.start();try{assertTrue(entered.await(2,TimeUnit.SECONDS));b.start();assertTrue(closeAttempt.await(2,TimeUnit.SECONDS));assertFalse(close.isDone());}finally{release.countDown();a.join(3000);if(b.getState()!=Thread.State.NEW)b.join(3000);}start.get(1,TimeUnit.SECONDS);close.get(1,TimeUnit.SECONDS);assertEquals(1,closed.get());assertThrows(IllegalStateException.class,launch::startConfigured);}
    @Test void closeBeforeConfigureOrStartCannotBeReopened(){var launch=new CodeIntentFixtureLaunchConfiguration((c,m,s)->{throw new AssertionError("No late allocation");});launch.close();assertThrows(IllegalStateException.class,()->launch.configure(enabled()));assertThrows(IllegalStateException.class,launch::startConfigured);}
    @Test void identicalConfigureWaitsForStartingOwnerWithoutSecondAllocation()throws Exception{
        var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var attempted=new CountDownLatch(1);var starts=new AtomicInteger();
        var launch=new CodeIntentFixtureLaunchConfiguration((c,m,s)->{starts.incrementAndGet();entered.countDown();try{assertTrue(release.await(2,TimeUnit.SECONDS));}catch(InterruptedException e){throw new AssertionError(e);}return ()->{};});var values=enabled();launch.configure(values);
        var start=new FutureTask<Void>(()->{launch.startConfigured();return null;});var configure=new FutureTask<Void>(()->{attempted.countDown();assertSame(launch,launch.configure(values).orElseThrow());return null;});
        var a=new Thread(start);var b=new Thread(configure);a.start();try{assertTrue(entered.await(2,TimeUnit.SECONDS));b.start();assertTrue(attempted.await(2,TimeUnit.SECONDS));assertFalse(configure.isDone());}finally{release.countDown();a.join(3000);if(b.getState()!=Thread.State.NEW)b.join(3000);}
        try{start.get(1,TimeUnit.SECONDS);configure.get(1,TimeUnit.SECONDS);assertEquals(1,starts.get());}finally{launch.close();}
    }
}
